/* Native station/EAPOL/CCMP controlled port. PMK and a fresh SNonce are inputs
 * from separately qualified producers, not generated by this transport. The
 * parent must still supply persistent ownership and an IP interface. */
#ifndef POLARIS_UEFI_WIFI_NETWORK_NATIVE_H
#define POLARIS_UEFI_WIFI_NETWORK_NATIVE_H
#include "uefi-wifi-keys-native.h"
#include "../../tools/polaris-wifi-ethernet.h"
#ifndef EFI_XNU_WIFI_NETWORK_NATIVE_AVAILABLE
#define EFI_XNU_WIFI_NETWORK_NATIVE_AVAILABLE 0
#endif
#if EFI_XNU_WIFI_NETWORK_NATIVE_AVAILABLE
#if !EFI_XNU_WIFI_KEYS_NATIVE_AVAILABLE
#error Native network requires native station and key transport
#endif
struct pmwn_state {
    uint64_t station,owner,opening;
    struct pwpa_state wpa;struct pmky_state keys;struct pwen_state ethernet;
    uint8_t pmk[32],nonce[32],early[2048];
    uint32_t ready,unknown,error,closed,submitted,tx_wait,tx_id,tx_kind,tx_status,tx_completed;
    uint32_t early_ready,early_bytes,early_peer,early_vdev,early_info,rx_dropped;
};
static inline void pmwn_close(struct pmwn_state*s)
{
    s->closed=1;pwpa_stop(&s->wpa);pwen_stop(&s->ethernet);
    pwch_wipe(s->pmk,32);pwch_wipe(s->nonce,32);pwch_wipe(s->early,sizeof(s->early));s->early_ready=0;
    /* DMA ownership is deliberately retained, even on a disconnected peer. */
}
static inline int pmwn_fail(struct pmwn_state*s,unsigned error)
{s->unknown=1;if(!s->error)s->error=error;pmwn_close(s);return -1;}
static inline int pmwn_live(struct pmwn_state*s)
{
    if(!s||s->ready!=1||s->unknown||s->error)return 0;
    struct pmst_state*p=(void*)(uintptr_t)s->station;
    return p->owner==s->owner&&p->opening==s->opening&&
        p->consumer==(s->keys.ready?(uintptr_t)&s->keys:(uintptr_t)s)&&pmst_live(p)&&
        (!s->keys.ready||pmky_live(&s->keys));
}
static inline int pmwn_begin(struct pmwn_state*s,struct pmst_state*p,const uint8_t pmk[32],const uint8_t nonce[32])
{
    if(!s||!p||!pmk||!nonce||!pwmc_zero(s,sizeof(*s))||!pmst_live(p)||p->consumer||
       p->client.station.security!=2||p->client.phase==9||!pwpa_nonzero(nonce,32))return 0;
    struct pmhd_state*d=(void*)(uintptr_t)p->data;struct pmht_state*t=(void*)(uintptr_t)d->parent;
    struct pmwi_state*w=(void*)(uintptr_t)t->wmi;struct pmhc_state*h=(void*)(uintptr_t)w->htc;
    const uint64_t address[]={(uintptr_t)p,p->scan,(uintptr_t)d,(uintptr_t)t,t->memory,t->wmi};
    const uint64_t size[]={sizeof(*p),sizeof(struct pmwsn_state),sizeof(*d),sizeof(*t),sizeof(struct pcdm_state),sizeof(*w)};
    if(!pmwi_child(h,(uintptr_t)s,sizeof(*s)))return 0;
    for(unsigned n=0;n<6;n++)if(!pwea_disjoint((uintptr_t)s,sizeof(*s),address[n],size[n]))return 0;
    s->station=(uintptr_t)p;s->owner=p->owner;s->opening=p->opening;
    pwch_copy(s->pmk,pmk,32);pwch_copy(s->nonce,nonce,32);s->ready=1;p->consumer=(uintptr_t)s;return pmwn_live(s);
}
static inline int pmwn_commit(struct pmwn_state*s)
{
    struct pmst_state*p=(void*)(uintptr_t)s->station;struct pmhd_state*d=(void*)(uintptr_t)p->data;
    struct pmsc_owner*o=(void*)(uintptr_t)s->owner;
    if(s->submitted&&!d->submitted){
        if((d->rings.tx_owner[s->tx_id]!=2&&d->rings.tx_owner[s->tx_id]!=3)||
           (s->tx_kind==2&&pwpa_sent(&s->wpa,o->last,1)!=1)||!pwen_sent(&s->ethernet))return pmwn_fail(s,1);
        s->submitted=0;
    }
    if(s->tx_wait&&d->rings.tx_owner[s->tx_id]==3){
        if(!pmhd_tx_ack(d,s->tx_id,&s->tx_status))return pmwn_fail(s,2);
        s->tx_wait=0;s->tx_completed++;
    }return 1;
}
static inline int pmwn_rx(struct pmwn_state*s,const uint8_t*raw,unsigned bytes,unsigned peer,unsigned vdev,unsigned info)
{
    /* An unread upper packet must not block HTT key confirmations or WMI.
     * Drop the later packet, not the physical receive buffer ownership. */
    if(s->ethernet.rx_ready){s->rx_dropped++;return 1;}
    int result=pwen_receive(&s->ethernet,raw,2048,bytes,peer,vdev,info);
    if(result<0)return pmwn_fail(s,3);
    if(result==2){
        struct pmsc_owner*o=(void*)(uintptr_t)s->owner;
        if(pwpa_receive(&s->wpa,s->ethernet.receive+14,s->ethernet.rx_bytes-14,o->last)<0)return pmwn_fail(s,3);
        /* Busy crypto/queued replies may drop duplicates; AP retransmission
         * is handled by the replay-bound handshake, never by reinstalling. */
        if(!pwen_ack(&s->ethernet))return pmwn_fail(s,3);
    }return 1;
}
/*1=progress,2=unhandled retained control event,3=authenticated Ethernet packet,
 *4=disconnected/handshake timeout,5=controlled port open. None means IP ready. */
static inline int pmwn_step(struct pmwn_state*s)
{
    if(!pmwn_live(s))return -1;if(s->closed)return 4;
    struct pmst_state*p=(void*)(uintptr_t)s->station;struct pmhd_state*d=(void*)(uintptr_t)p->data;
    struct pmht_state*t=(void*)(uintptr_t)d->parent;struct pmwi_state*w=(void*)(uintptr_t)t->wmi;
    struct pmhc_state*h=(void*)(uintptr_t)w->htc;struct pmsc_owner*o=(void*)(uintptr_t)s->owner;
    int result=s->keys.ready?pmky_step(&s->keys):pmst_step(p);
    if(result<0)return pmwn_fail(s,4);if(result==4){pmwn_close(s);return 4;}
    if(pmwn_commit(s)<0)return -1;
    if(!s->wpa.opened&&p->client.station.associated){
        if(!p->client.peer_valid||!pwpa_open(&s->wpa,&p->client.station,s->pmk,s->nonce,o->last)||
           !pwen_open(&s->ethernet,&p->client.station,p->client.peer_id))return pmwn_fail(s,5);
        pwch_wipe(s->pmk,32);pwch_wipe(s->nonce,32);
    }
    if(s->keys.ready&&!pwen_keys(&s->ethernet,&s->keys.client,&s->wpa))return pmwn_fail(s,6);
    if(s->early_ready&&s->wpa.opened){
        if(pmwn_rx(s,s->early,s->early_bytes,s->early_peer,s->early_vdev,s->early_info)<0)return -1;
        pwch_wipe(s->early,sizeof(s->early));s->early_ready=0;
    }
    if(result==3){
        if(!d->frame_ready)return pmwn_fail(s,7);
        if(s->wpa.opened){if(pmwn_rx(s,d->receive,d->rx_bytes,d->rings.rx_peer,d->rings.rx_vdev,d->rings.rx_info)<0)return -1;}
        else if(!s->early_ready){
            pwch_copy(s->early,d->receive,2048);s->early_ready=1;s->early_bytes=d->rx_bytes;
            s->early_peer=d->rings.rx_peer;s->early_vdev=d->rings.rx_vdev;s->early_info=d->rings.rx_info;
        }else s->rx_dropped++;
        if(!pmhd_ack(d))return pmwn_fail(s,7);
    }
    if(s->wpa.opened){
        int crypto=pwpa_step(&s->wpa,o->last);if(crypto<0)return pmwn_fail(s,8);
        if(!crypto){pmwn_close(s);return 4;}
        if(crypto==2&&!s->ethernet.tx_bytes&&!s->submitted){
            if(!pwen_eapol(&s->ethernet,s->wpa.reply,s->wpa.reply_bytes))return pmwn_fail(s,8);s->tx_kind=2;
        }
    }
    if(result==2)return 2;
    if(s->wpa.keys_ready&&!s->wpa.pending&&!s->keys.ready&&p->client.up_published&&
       !p->submitted&&!p->mgmt_wait&&!h->client.pending&&!h->frame_kind){
        if(!pmky_begin_owned(&s->keys,p,&s->wpa,(uintptr_t)s))return pmwn_fail(s,9);
    }
    if(s->ethernet.tx_bytes&&!s->submitted&&!s->tx_wait&&p->client.up_published&&!p->submitted&&
       !p->mgmt_wait&&!h->client.pending&&!d->submitted&&(!s->keys.ready||s->keys.completed)){
        pwch_copy(d->send,s->ethernet.transmit,s->ethernet.tx_bytes);
        int sent=pmhd_send(d,s->ethernet.tx_bytes,2,0,16,s->ethernet.tx_plain);if(sent<0)return pmwn_fail(s,10);
        if(sent){s->tx_id=d->rings.tx_id;s->tx_wait=s->submitted=1;if(pmwn_commit(s)<0)return -1;}
    }
    return s->ethernet.rx_ready?3:s->ethernet.authorized?5:1;
}
static inline int pmwn_send(struct pmwn_state*s,const uint8_t*frame,unsigned bytes)
{
    if(!pmwn_live(s)||s->closed||s->submitted||s->tx_wait||s->wpa.pending||!s->keys.completed)return 0;
    if(!pwen_data(&s->ethernet,frame,bytes))return 0;s->tx_kind=1;return 1;
}
static inline int pmwn_ack(struct pmwn_state*s)
{return pmwn_live(s)&&!s->closed&&s->ethernet.rx_kind==1&&pwen_ack(&s->ethernet);}
#endif
#endif
